import{_ as a,o as t,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"3.3.2 Update Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/profile/3-3-2-update-profile/spec.md","filePath":"feature/profile/3-3-2-update-profile/spec.md"}'),r={name:"feature/profile/3-3-2-update-profile/spec.md"};function n(l,e,s,d,c,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="_3-3-2-update-profile" tabindex="-1">3.3.2 Update Profile <a class="header-anchor" href="#_3-3-2-update-profile" aria-label="Permalink to &quot;3.3.2 Update Profile&quot;">​</a></h1><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a signed-in user saves edits to their profile fields on <code>/profile</code>, or selects a new avatar image in the avatar upload dialog.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Any authenticated user (role <code>USER</code>); a user updates only their own profile.</li><li><strong>Purpose:</strong> Let the user keep their personal information accurate — display name, phone number, professional title, bio, portfolio links, working language, timezone, notification preferences — and refresh their avatar.</li><li><strong>Interface:</strong> The Profile screen at <code>/profile</code> in edit mode: an editable full-name field, a phone field, a job-title field, a working-language field, a bio textarea, a repeatable portfolio-URL list, a timezone selector, and a Save button. Saving submits a full update of the signed-in user&#39;s own profile (PUT semantics). The avatar is not part of that form — it is changed through a separate image-upload action opened from the avatar upload dialog. Cancel discards in-progress edits and restores every field (including the four fields listed above) to their last-saved values, not just full name and phone.</li><li><strong>Data Processing:</strong> The system loads the user record, writes the submitted full name, phone number, professional title, bio, portfolio URLs and working language directly onto the user record, merges the submitted timezone and notification preferences into the stored preferences data (only fields actually submitted are overwritten; fields left out keep their previous values), persists the record, and returns the updated profile. The avatar upload is handled independently: the file is validated, stored in file storage, the previous avatar file is removed when one exists, and the new avatar reference is saved.</li><li><strong>Known gap (not yet implemented):</strong> the spec&#39;s <code>notificationPreferences</code> field is wired end-to-end on the backend (merged into the stored preferences JSON, returned in the response) but the Profile screen has no notification-preference UI — there is nothing on <code>/profile</code> for the user to toggle. This is a real gap, not a stale spec claim about the backend; the backend behavior described above is accurate and code-verified.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Profile Screen (<code>/profile</code>, edit mode):</p><ul><li>Center: the profile card in edit mode — full-name input (required), phone input, job-title input, working-language input, bio textarea, a repeatable list of portfolio URL inputs (add/remove), and a timezone selector. Email address and avatar are displayed but are not editable from this form. Notification preferences have no UI yet (see Known gap above).</li><li>Buttons: Save (primary) — submits the update; Cancel — discards the changes and restores every editable field to its last-saved value.</li><li>Footer: none.</li></ul><p>Figure — Avatar Upload Dialog:</p><ul><li>Center: image file selector and preview of the selected image.</li><li>Buttons: Upload — submits the selected image; Cancel — closes the dialog without changes.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> <code>fullName</code>; and an image file for the avatar upload action.</li><li><strong>Input optional:</strong> <code>phone</code>, <code>professionalTitle</code>, <code>bio</code>, <code>portfolioUrls</code>, <code>workingLanguage</code>, <code>timezone</code>, <code>notificationPreferences</code>.</li><li><strong>System data:</strong> <code>users</code> (<code>fullName</code>, <code>phone</code>, <code>professionalTitle</code>, <code>bio</code>, <code>portfolioUrls</code>, <code>workingLanguage</code>, preferences JSON holding the timezone and notification preferences, <code>avatarUrl</code>).</li><li><strong>Output:</strong> The complete updated profile field set — <code>userId</code>, <code>email</code>, <code>fullName</code>, <code>avatarUrl</code>, <code>phone</code>, <code>role</code>, <code>workspaceId</code>, <code>professionalTitle</code>, <code>bio</code>, <code>portfolioUrls</code>, <code>workingLanguage</code>, <code>timezone</code>, <code>notificationPreferences</code>, <code>createdAt</code>; the avatar upload returns the new <code>avatarUrl</code>.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-19:</strong> The update request carries no email field and no avatar field, so neither can be submitted through this action — this is structural (there is no place to carry them), not a silent discard by the system. Changing the email address is out of scope for this feature.</li><li><strong>Implementation note (no dedicated global BR):</strong> Only the fields actually submitted (non-empty) are overwritten inside the stored preferences data; fields left out keep their previous values.</li><li><strong>BR-20:</strong> Avatar upload: file required, content type must start with <code>image/</code>, max 5 MB.</li><li><strong>Implementation note (no dedicated global BR):</strong> When a new avatar is uploaded successfully, the previous avatar file in file storage is deleted.</li><li><strong>Implementation note (no dedicated global BR):</strong> Removing the avatar (setting it to none) is a valid action and results in the default initials avatar, not an error.</li><li><strong>Implementation note (no dedicated global BR):</strong> The avatar upload is independent of the profile field update; one failing does not roll back or block the other.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li><code>fullName</code> empty or blank → 400 <code>VALIDATION_ERROR</code>, Display: MSG02.</li><li>The preferences data cannot be serialized (rare) → 400 <code>INVALID_REQUEST</code>, Display: MSG02.</li><li>Avatar upload: no file provided (BR-20) → 400 <code>NO_FILE_PROVIDED</code>, Display: MSG27; the content type is not an image (BR-20) → 400 <code>INVALID_FILE_TYPE</code>, Display: MSG28; the file exceeds 5 MB (BR-20) → 400 <code>FILE_TOO_LARGE</code>, Display: MSG29; the file cannot be read → 400 <code>UPLOAD_FAILED</code>, Display: MSG38.</li><li>Missing, expired, or invalid access token → 401 <code>UNAUTHORIZED</code>, Display: MSG22.</li><li>The user record no longer exists (theoretical) → 404 <code>USER_NOT_FOUND</code>, Display: MSG38.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The user edits the form on <code>/profile</code> and clicks Save.</li><li>The application submits the changed profile fields.</li><li>The system loads the user record and writes the submitted full name and phone number.</li><li>The system merges the submitted timezone and notification preferences into the stored preferences data, overwriting only the fields submitted.</li><li>The system persists the record and returns the complete updated profile.</li><li>The application shows a success confirmation and refreshes the displayed profile immediately, without a page reload; toast MSG26.</li><li>Separately, the user selects an image in the avatar upload dialog and submits it.</li><li>The system validates the file (BR-20), stores it, deletes the previous avatar file when one exists, saves the new avatar reference, and returns the new avatar value; toast MSG30.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>3.a1: The user record no longer exists (theoretical) → 404 <code>USER_NOT_FOUND</code>, toast MSG38. 3.a2: The user is signed out and returned to /login.</li><li>3.b1: <code>fullName</code> submitted empty or blank → 400 <code>VALIDATION_ERROR</code>, Display: MSG02. 3.b2: The form stays open with the error shown; the user re-enters a full name and saves again.</li><li>4.a1: The preferences data cannot be serialized (rare) → 400 <code>INVALID_REQUEST</code>, Display: MSG02. 4.a2: The form stays open; the user retries Save.</li><li>8.a1: No file is provided for the avatar upload (BR-20) → 400 <code>NO_FILE_PROVIDED</code>, Display: MSG27. 8.a2: The user selects a file and submits again.</li><li>8.b1: The selected file&#39;s content type is not an image (BR-20) → 400 <code>INVALID_FILE_TYPE</code>, Display: MSG28. 8.b2: The user selects an image file and submits again.</li><li>8.c1: The selected file exceeds 5 MB (BR-20) → 400 <code>FILE_TOO_LARGE</code>, Display: MSG29. 8.c2: The user selects a smaller image and submits again.</li><li>8.d1: The file cannot be read during upload → 400 <code>UPLOAD_FAILED</code>, toast MSG38. 8.d2: The user retries the upload.</li><li>8.e1: The avatar is removed instead of replaced (BR-20) → the default initials avatar is shown, with no error. 8.e2: No retry is needed; the profile card reflects the default initials avatar.</li><li>N.a1: Missing, expired, or invalid access token at any step → 401 <code>UNAUTHORIZED</code>, toast MSG22. N.a2: The user signs in again at /login (3.2.2).</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li><code>fullName</code>, <code>phone</code>, <code>professionalTitle</code>, <code>bio</code>, <code>portfolioUrls</code>, <code>workingLanguage</code>, <code>timezone</code>, and <code>notificationPreferences</code> hold the submitted values; fields left out of the request keep their previous values.</li><li>The avatar reference reflects the most recent successful upload, or the default initials avatar when the avatar was removed.</li><li>The avatar is stored independently of the profile field update.</li></ul>',24)])])}const f=a(r,[["render",n]]);export{p as __pageData,f as default};
